// Jeffrey-Bolker decision theory on a small finite algebra (page 7.1).
// Pure JavaScript, no DOM, so the same code runs in the browser and in Node tests.
//
// The algebra is generated by atoms: one atom for each (action, state) pair.
// A belief function P gives each atom a probability; a desire function D gives each atom a desirability.
// For any proposition A (a set of atoms) with P(A) > 0:
//   v(A) = sum over atoms w in A of P(w) D(w),   D(A) = v(A) / P(A).
// So D(A) is the P-weighted average of the desirabilities of the ways A can be true (Herrmann and
// Levinstein 2026, section 3.4.3). Bolker's uniqueness theorem (their footnote 43): two pairs represent
// the same preferences iff v' = a v + b P and P' = c v + d P with ad - bc > 0 (and P' a probability).
// On atoms this reads P'(w) = P(w)(c D(w) + d) and D'(w) = (a D(w) + b) / (c D(w) + d).

export const ACTIONS = ['Edit the parser', 'Edit the renderer', 'Search the rest'];
export const STATES = ['parser', 'renderer', 'elsewhere'];

// Atoms are indexed k = action * nStates + state.
export function atoms(pAction, pState, D) {
  const P = [], Dv = [];
  for (let i = 0; i < pAction.length; i++) {
    for (let j = 0; j < pState.length; j++) { P.push(pAction[i] * pState[j]); Dv.push(D[i][j]); }
  }
  return { P, D: Dv, nA: pAction.length, nS: pState.length };
}

// Probability and desirability of a proposition given as a list of atom indices.
export function prob(m, A) { return A.reduce((s, k) => s + m.P[k], 0); }
export function desir(m, A) {
  const p = prob(m, A);
  return p > 0 ? A.reduce((s, k) => s + m.P[k] * m.D[k], 0) / p : NaN;
}

export const actionAtoms = (m, i) => Array.from({ length: m.nS }, (_, j) => i * m.nS + j);
export const stateAtoms = (m, j) => Array.from({ length: m.nA }, (_, i) => i * m.nS + j);
export const allAtoms = (m) => m.P.map((_, k) => k);

// Credence in each state given the action: P(state | action).
export function conditional(m, i) {
  const A = actionAtoms(m, i), p = prob(m, A);
  return A.map((k) => m.P[k] / p);
}

// Desirability of each action, by averaging over the states.
export function actionValues(m) {
  return Array.from({ length: m.nA }, (_, i) => desir(m, actionAtoms(m, i)));
}

export function argmax(xs) { let b = 0; xs.forEach((x, i) => { if (x > xs[b]) b = i; }); return b; }

// Order of the actions from most to least desirable (indices).
export function ranking(xs) { return xs.map((x, i) => [x, i]).sort((p, q) => q[0] - p[0]).map((p) => p[1]); }

// The value of d that makes P' a probability: P'(T) = c D(T) + d must equal 1, since P(T) = 1 and v(T) = D(T).
export function normalizingD(m, c) { return 1 - c * desir(m, allAtoms(m)); }

// Checks Bolker's conditions for the constants on this algebra.
// c D + d > 0 is needed on every proposition with positive probability; since D(A) is an average of atom
// desirabilities and c D + d is linear in D, it suffices to check the atoms.
export function check(m, { a, b, c, d }) {
  if (!(a * d - b * c > 1e-12)) return { ok: false, why: 'ad − bc must be positive' };
  for (let k = 0; k < m.P.length; k++) if (m.P[k] > 0 && !(c * m.D[k] + d > 1e-12)) return { ok: false, why: 'cD + d must be positive for every proposition' };
  return { ok: true };
}

// The transformed pair, on atoms. Exactly the formula above; P' sums to c D(T) + d.
export function transform(m, { a, b, c, d }) {
  const P = m.P.map((p, k) => p * (c * m.D[k] + d));
  const D = m.D.map((x) => (a * x + b) / (c * x + d));
  return { ...m, P, D };
}

// Rescales a measure to total 1. Doing this to P' is the same as dividing a, b, c, d by P'(T),
// which leaves D' unchanged (see tools/test-page-7-1.mjs).
export function normalize(m) {
  const t = m.P.reduce((s, p) => s + p, 0);
  return { ...m, P: m.P.map((p) => p / t) };
}

// Every nonempty proposition of the algebra, as lists of atom indices (2^n - 1 of them).
export function allPropositions(n) {
  const out = [];
  for (let mask = 1; mask < 1 << n; mask++) {
    const A = [];
    for (let k = 0; k < n; k++) if (mask & (1 << k)) A.push(k);
    out.push(A);
  }
  return out;
}

// Do two pairs order the given propositions the same way (ties included)?
export function sameOrdering(m1, m2, props, tol = 1e-9) {
  const v1 = props.map((A) => desir(m1, A)), v2 = props.map((A) => desir(m2, A));
  for (let i = 0; i < props.length; i++) {
    if (!(prob(m1, props[i]) > 0)) continue;
    for (let j = i + 1; j < props.length; j++) {
      if (!(prob(m1, props[j]) > 0)) continue;
      const s1 = Math.abs(v1[i] - v1[j]) < tol ? 0 : Math.sign(v1[i] - v1[j]);
      const s2 = Math.abs(v2[i] - v2[j]) < tol ? 0 : Math.sign(v2[i] - v2[j]);
      if (s1 !== s2) return false;
    }
  }
  return true;
}
